// Keep the original regeneration command, but use the table-specific crops.
// Attack and critical files are generated by their dedicated extractors.
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const extractor = fileURLToPath(new URL('./extract-reference-tables.py', import.meta.url));
